) AS (
  VALUES 
    (40::BIGINT, 'muy buena profesora, explica bien. eso si deja tareas todas las semanas entonces ir a clase, estar al día con la materia, hacer las tareas semanales es la clave para pasar el curso. sabe mucho de la materia, entonces se aprende mucho y los exámenes siempre son alguna de la tareas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2026-07-20T00:00:00+00:00'::TIMESTAMPTZ, '4b13784f1c1b9520bc125b93e75c6aa88c599d4916976118eca5e9b16c51b769'::TEXT, ARRAY[1707, 2361]::BIGINT[]),
    (40::BIGINT, 'No matriculen con ella. Es muy desorganizada y nunca contesta mensajes por ningun medio por lo que es imposible comunicarse con ella. No explica absolutamente nada entonces hay que buscar ayuda externa. Deja tareas largas de temas que ni se introdujeron. No le da nada de prioridad a la clase'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2026-07-06T00:00:00+00:00'::TIMESTAMPTZ, 'd4829846e40f4cac36d2112d77939f25f0965023324663d057d0c6847a4e4fa4'::TEXT, ARRAY[2361]::BIGINT[]),
    (40::BIGINT, 'es terrible. no explica nada, las tareas y exámenes no son como lo que se ve en clase y nunca responde cuando uno necesita ayuda. esta metida en tantos proyectos que no tiene tiempo para ser buena profesora. si matricula con ella prepárese para aprender solo o para buscar ayuda externa.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2026-05-07T00:00:00+00:00'::TIMESTAMPTZ, '330c0a94d64cf1630c9ce09fffc8bcb105b5e7f7885e017c332dfbd51b06f09b'::TEXT, ARRAY[2366, 2361, 1707]::BIGINT[]),
    (40::BIGINT, 'Ella en general no da sus clases, solo da lo más básico de la teoría y vea usted como resuelve, sobre todo con sus trabajos que no se parecen en nada a lo que explica.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2026-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'b0c0e9041ff412ad3dc1821b3b6ad3c731dfbcb2b1cebc4df70987bb1cb122ab'::TEXT, ARRAY[2366, 2361, 1707]::BIGINT[]),
    (40::BIGINT, 'La mejor profesora para llevar TODAS las contabilidades. Es clara, ayuda y sus trabajos son sencillos de comprender.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-13T00:00:00+00:00'::TIMESTAMPTZ, '0d0eaca11ea6390a7e75fc944ac0d325fc492f70aa01e62554edaf6724656f1f'::TEXT, ARRAY[1707, 2361, 2366]::BIGINT[]),
    (40::BIGINT, 'La profe es buena gente pero practicamente es aprender solo o pagar tutorías aparte para entender, deja trabajos bastante largos cada semana que tienen muy poco valor en la nota.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'f12361a9a898a78da600803690d1069ec588e4f6227cd0d46532c17a4a2da81b'::TEXT, ARRAY[1707]::BIGINT[]),
    (40::BIGINT, 'A veces puede ser un poco confuso pero siempre esta dispuesta a resolver dudas, aunque presencial por que a veces puede costar que responda correos. Si uno presta atención en clase, procura entender los temas y hace los trabajos se puede fácilmente sacar 80 o más.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, '61d91064723b6d2f2f9e5d3232dac33a79f23c40cf5e3554b593e8c37560062d'::TEXT, ARRAY[1708]::BIGINT[]),
    (40::BIGINT, 'Solo utiliza aula invertida y si uno le pide que explique pone un montón de excusas. Cuando uno le pide actitud de mejora se molesta'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2023-12-15T00:00:00+00:00'::TIMESTAMPTZ, '340539498a5f9759fec2994b89fd727175d910a0bf28d9b715a886b116303103'::TEXT, ARRAY[1707]::BIGINT[]),
    (40::BIGINT, 'Aprenda solo.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, '1518b45d36f846ebbb0a68c9e81db91d7e34ee79bb18e09f8985025b19ad5bd8'::TEXT, ARRAY[1707]::BIGINT[]),
    (40::BIGINT, 'No ofrece el mismo trato a los grupos'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-15T00:00:00+00:00'::TIMESTAMPTZ, '144437e196a6a1723924b1855e21911c144dc6bd61cfac63f78a3e58acaa43e5'::TEXT, ARRAY[2366, 2361, 1707]::BIGINT[]),
    (40::BIGINT, 'Es una excelente profe, siempre te ayuda con las dudas y está disponible para retomar temas si es necesario.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '228b3c5439f7f75a7ab8c9035de6ee55257d3b1fe7631800cf19862ea4cbf9ef'::TEXT, ARRAY[2361]::BIGINT[]),
    (40::BIGINT, 'Excelente profe. Al principio puede ser confuso él aula invertida pero uno se acostumbra. Siempre dispuesta a ayudarte y muy respetuosa si usted no entiende. Definitivamente ama lo que hace y lo transmite al estudiante!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '36cd01cb3590f5722a645c1d69d1aa98e5bafa41fd9a6cf3bc571f3d5d2e5d42'::TEXT, ARRAY[1708]::BIGINT[]),
    (40::BIGINT, 'Es la única profe en toda la escuela que sabe aplicar el aula invertida. Es demasiado clara y te motiva a estar con ella Es una profe con la que te sientes acompañado, siempre claro y su dinamismo hace que la clase sea amena Matriculen con ella, vale totalmente la pena'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'd99c0fea82314afd912dc749c406b4bf3f4c3c0973e31b508a0188be4681c9dc'::TEXT, ARRAY[1707, 1708]::BIGINT[]),
    (40::BIGINT, 'Deja tarea todas las semanas y se revisa la semana siguiente y toma mucho tiempo en esto para asegurarse que todos entiendan. Deja una practica una semana antes del examen que es practicamente igual al examen'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2023-02-21T00:00:00+00:00'::TIMESTAMPTZ, 'bbb846901fff125437d1a33cd16c231d53970e4eaba9a95c92017abf8bddc8ba'::TEXT, ARRAY[2366]::BIGINT[]),
    (40::BIGINT, 'llevé Conta 1 con ella y fue super facil, deja trabajos semanales pero son super facil y tambien los examenes. Es una profesora excelente, se las recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, '0a76e70d3a3e9c4ff96f5a42cbb731a8df96f9a260e0ea79a4fe707265e4122a'::TEXT, ARRAY[1707]::BIGINT[]),
    (40::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-16T00:00:00+00:00'::TIMESTAMPTZ, '9b17d94c1c4ffc9217a82ee2c58c031b994f0fc50e7593d19113e7ac46010808'::TEXT, ARRAY[1707]::BIGINT[]),
    (40::BIGINT, 'Buena gente aunque no explica nada a fondo porque su intención es que aprenda por su cuenta. Deja tareas cada semana que a veces son confusas porque uno no tiene ni idea de lo que se hace. Los examenes son igual a la práctica entonces si entiende eso le va bien.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'f410a0d09bdb4caa7aa2d361886effac05cde5259a84699dca0823ea8d5e3ad7'::TEXT, ARRAY[1707]::BIGINT[]),
    (40::BIGINT, 'La profe es muy buena gente, en general. Es algo enojona y se molesta fácil. No explica nada, casi que todo lo que usted aprende es intuitivo, consiga compas para hacer todo juntos. Los exámenes son iguales a las practicas y son fáciles. Se pasa bien el curso, pero hay que tener paciencia con ella.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2022-11-27T00:00:00+00:00'::TIMESTAMPTZ, '8a59e105e0b442ea88e3a0cef4fe6532c2d9850d8b7dd833096fe23a7820562f'::TEXT, ARRAY[1707]::BIGINT[]),
    (40::BIGINT, 'No es clara cuando da las instrucciones, suele cometer muchos errores al momento de explicar la información, se enoja muy rápido, pone muchos trabajos y no da retroalimentación, solo sube las respuestas y uno debe de tratar de comprender porque fue el error.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2022-10-27T00:00:00+00:00'::TIMESTAMPTZ, '22c6061b3689be0a64dfa067b6ea42f01503b753d0dbd6e286418a962c2f8bcc'::TEXT, ARRAY[1707]::BIGINT[]),
    (40::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases excelentes']::TEXT[], '2017-01-22T00:00:00+00:00'::TIMESTAMPTZ, '885a0720eeba092266ac39c1139141587ce7b7c18b1f7f3eb5e146f9bc1c5d1e'::TEXT, ARRAY[1707]::BIGINT[]),
    (40::BIGINT, 'Excelente profesora, un poco enojona, pero explica bien. La recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2016-11-12T00:00:00+00:00'::TIMESTAMPTZ, '7d4387a6b3acbc7df9c3fd04d174e22b1546629d60ea351021e0b3b6f69c8e5e'::TEXT, ARRAY[1206]::BIGINT[]),
    (40::BIGINT, 'Muy estricta pero excelente profesora, se aprende.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2016-10-30T00:00:00+00:00'::TIMESTAMPTZ, '0237a6db717d4303e91c546392850d515712e60da1bab3363cbddd1ffd7e51da'::TEXT, ARRAY[1707]::BIGINT[]),
    (40::BIGINT, 'Una persona muy exigente, ordenada, las cosas se deben hacer a su manera, pero lo que más me gusto y fue que le refute un trabajo, y como ella no esta 100% segura me dijo "preguntare en Catedra" y a los días me dijo tienes razón y me dio todos los puntos del trabajo..!!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Brinda apoyo']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'e1dffb608db899214ae05f5e24bc2d60b260b5b12a51b15e5b7f520966ca3a7a'::TEXT, ARRAY[2361]::BIGINT[]),
    (40::BIGINT, 'Ella es una persona que sabe mucho, y si uno tiene dudas no duda en atenderte. Da su numero de telefono y es posible buscarla para preguntarle cosas o trabajos. Pone muchos trabajos, pero no son demasiado dificiles y es posible pasar.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'a601191c09cd6bc2960643ea2d6af1bc81cf762d35a6c77e0c40053dc6b7152b'::TEXT, ARRAY[1707]::BIGINT[]),
    (40::BIGINT, 'Pretende que haga perfecto y como ella quiere las cosas, muy cerrada para dar la clase'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '125a01a8a9b400f3c9b6d2b73cf97a85665dca873708cb175ac27cf8542210fe'::TEXT, ARRAY[1707]::BIGINT[]),
    (40::BIGINT, 'Es buena pero deja muchísimos trabajos de investigación. A veces deja tareas de un día para otro y hay que exponerlas al siguiente día, junto con revisión de capítulo del libro más algún quiz por ejemplo. No he tenido una clase donde no se tuviera que entregar al menos 2 trabajos de investigación.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2016-03-12T00:00:00+00:00'::TIMESTAMPTZ, 'd47334ba6f08bb962dd5cbbab3e86c043537cae15fe966215009cfbd507a7dc2'::TEXT, ARRAY[98, 2363, 2359, 96]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
